+				s/\s*$//g;
+				$func.=':'.$_ unless $_ eq "";
+			}
+
+			push @inline, $func;
+		}
+
+		unshift @stack, @inline;
+	} else {
+		warn "Unrecognized line: $_";
+	}
+}
+
+foreach my $k (sort { $a cmp $b } keys %collapsed) {
+	print "$k $collapsed{$k}\n";
+}
